// src/lib/compute-api/handler.ts
async function computeApiRateLimit(req, id = COMPUTE_RATE_LIMIT_ID) {
  if (process.env.NODE_ENV !== "production") return "unavailable";
  try {
    const result = await checkRateLimit(id, { headers: req.headers });
    if (result?.error === "not-found") return "unavailable";
    if (result?.rateLimited === true) return "limited";
    if (result?.rateLimited === false && result.error === void 0) return "allowed";
    return "unavailable";
  } catch {
    return "unavailable";
  }
}

